const item = $json;

// 1. Проверка темы
const subject = item.Subject || '';
const subjectRegex = /^[A-Za-z][0-9]+$/;
const isSubjectValid = subjectRegex.test(subject);

// 2. Проверка переписки
const messages = item.Messages || [];
const hasReplies = messages.length > 1;

// Возвращаем тот же item, дополненный флагами
return {
  ...item,
  subject_is_valid: isSubjectValid,
  has_replies: hasReplies
};

