={
  "type": "object",
  "required": [
    "thread_id",
    "message_id",
    "email_subject",
    "Snippet", 
    "load_number",
    "document_type",
    "document_label",
    "secondary_document_types",
    "manual_review",
    "owner",
    "confidence",
    "request_summary",
    "evidence",
    "notes"
  ],
  "properties": {
    "thread_id": { "type": "string" },
    "message_id": {"type": "string"},
    "email_subject": { "type": "string" },
    "Snippet": {"type": "string"},
    "load_number": {
      "type": ["string", "null"]
    },
    "document_type": {
      "type": "string",
      "enum": [
        "CUSTOMER TENDER",
        "CARRIER CONFIRMATION",
        "BOL or POD",
        "UNKNOWN"
      ]
    },
    "document_label": {
      "type": "string",
      "enum": ["RC", "CC", "BOL", "UNKNOWN"]
    },
    "secondary_document_types": {
      "type": "array",
      "items": {
        "type": "string",
        "enum": [
          "CUSTOMER TENDER",
          "CARRIER CONFIRMATION",
          "BOL or POD"
        ]
      }
    },
    "manual_review": {
      "type": "boolean",
      "description": "true = manual processing, false = automatic processing"
    },
    "owner": {
      "type": ["string", "null"],
      "description": "Internal owner identified via tool (agent / manager). Null if not found."
    },
    "confidence": {
      "type": "number",
      "minimum": 0,
      "maximum": 1
    },
    "request_summary": {
      "type": "string"
    },
    "evidence": {
      "type": "object",
      "required": ["keywords_found", "quotes"],
      "properties": {
        "keywords_found": {
          "type": "array",
          "items": { "type": "string" }
        },
        "quotes": {
          "type": "array",
          "items": { "type": "string" },
          "maxItems": 3
        }
      }
    },
    "notes": {
      "type": "string"
    }
  }
}

