parameters.jsCode:
const seen = new Set();
const result = [];

for (const item of $input.all()) {
  const fileName = item.json.File_Name || '';
  const subject = item.json.Subject || '';

  const key = `${fileName}__${subject}`;

  if (!seen.has(key)) {
    seen.add(key);
    result.push(item);
  }
}

return result;
